import json,csv,re
from pathlib import Path
P=Path(__file__).parent
items=[]; talks=[]; problems=[]; corrections=[]
def talk(record,date,speaker,pages,title,summary,kind="talk"):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def add(record,pages,kind,title,notes,statement,reconstruction,fate,refs=(),cls="E",status="",literal="correct with missing hypotheses",match="exact",verification="read the result",development="annotated",problem="",worth="",confidence="high",speaker=None):
    n=1+sum(x["record"]==record for x in items)
    d=dict(id=f"1979-{record}.{n}",record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{"class":cls},fate=fate,present_status=status or r"As of November 2026, the stated, qualified result is established; the notebook wording is interpreted only with the hypotheses specified above.",literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker:d["speaker"]=speaker
    items.append(d); return d["id"]
def prob(id,title,statement,occurrences,status,refs):
    problems.append(dict(id=id,title=title,statement=statement,occurrences=occurrences,status=status,status_date="2026-11",refs=refs))
def corr(page,place,reads,correct,evidence,applies="both",type="faithful_error"):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=correct,evidence=evidence,applies_to=applies,type=type))
def save():
    for name,data in [("talks",talks),("items",items),("problems",problems)]:
        (P/(name+".json")).write_text(json.dumps(sorted(data,key=lambda x:(x.get("record",0),int(x["id"].split(".")[-1]) if "." in x.get("id","") else 0)) if name!="problems" else data,ensure_ascii=False,indent=2)+"\n")
    with (P/"corrections.csv").open("w",newline="") as f:
        w=csv.DictWriter(f,["page","place","transcription_reads","should_read","evidence","applies_to","type"]);w.writeheader();w.writerows(corrections)

talk(462,"1979-09-24","Renata Kallosh","P000840-P000843","Quantum gravity, higher-spin indices and superselfduality",
 r"The actual new talk begins on P000841 and ends on P000842. Kallosh reports on the Cambridge relativity meeting, then describes higher-spin zero-mode formulae and self-dual supergravity. P000840 is a carry-in from the preceding notebook material: its vertex-model, Yang--Baxter and Ising observations were already indexed as 1978-460.12--20. They are preserved as provenance, not reassigned to Kallosh or duplicated as 1979 occurrences. The catalogue page interval is retained verbatim. The programme of a superspace index theorem is distinguished from the concrete index computations and from any claim of unrestricted ultraviolet finiteness.")
talk(463,"1979-09-24","V. E. Zakharov","P000841-P000847","Degenerate dispersion laws, resonances and integrability",
 r"The talk begins on P000843, after Kallosh's report. Zakharov studies additional additive functions on wave-resonance manifolds, difference-curve parametrizations, dressing and a necessary resonance test for extra Hamiltonian integrals. Arnold connects this with translation surfaces, Poincaré obstructions and formal Birkhoff normal form. The subsequent programme appears in Zakharov--Schulman (1980, 1988) and the later Balk--Ferapontov web classification (1994); one additional collision invariant and infinitely many are distinct hypotheses. None of these statements identifies every notion of nonlinear integrability with degenerate scalar dispersion. P000847 ends with Gelfand's reading programme.")
talk(464,"1979-10-01","I. M. Gelfand","P000848-P000849","Spinors, quaternions and the Dirac equation",
 r"P000848 contains Gelfand's introductory discussion of spinors, the projective action of two-component vectors, Hamilton's square-root idea and physical consequences of the Dirac theory. The quaternion conclusion requires an extra quotient relation: three anticommuting square roots of minus one alone generate a Clifford algebra. Kallosh's subsequent programme begins at the foot of the same page.")
talk(465,"1979-10-01","Renata Kallosh","P000848-P000854","Spinor calculus and gravitational index theorems",
 r"The eight-part programme on P000848 is followed on P000849--P000853 by two-spinor calculus, self-duality, Laplace-type operators, heat coefficients and higher-spin spectral pairings. The notes themselves correct a proposed interpretation of the nonzero-mode term as a common eigenvalue multiplicity. They also contain incompatible numerical versions of an index formula on P000841 and P000853; these are recorded without silently repairing an unverified normalization. The dated heading on P000854 starts the next meeting.")
talk(466,"1979-10-08","I. M. Gelfand","P000852-P000855","Reading programme and exercises",
 r"The actual contribution is the opening of P000854: a reading programme and exercises on Gaussian and quartic Fourier integrals and on self-adjoint operators for a symplectic form. The exercises are definite mathematical items, although the contribution is primarily a programme. Their solutions must distinguish the self-adjoint relation for an alternating form from the Hamiltonian, skew-adjoint relation.",kind="plan")
talk(467,"1979-10-08","S. G. Gindikin","P000853-P000860","Twistors and the conformal compactification of Minkowski space",
 r"Starting on P000854, Gindikin describes the Hermitian space of signature (2,2), its two-plane Grassmannian, tube domains, the real Minkowski chart and null incidence. This continues the geometry of 1978-455.1. The manuscript's unrestricted affine chart stabilizer includes dilations, and its final point/ray correspondence interchanges the two sides of the twistor incidence relation. The higher-dimensional challenge is a programme, not a unique conjecture.")
talk(468,"1979-10-15","F. A. Berezin","P000858-P000863","Grassmann algebra, supermatrices and classification problems",
 r"The dated lecture begins on P000859 and ends with two explicit matrix problems at the top of P000862. Gelfand proposes graph analogues of the even Grassmann algebra; Gindikin then recalls the BGG description of projective bundles and asks for actual maps and a Grassmannian counterpart. The repeated-body-spectrum problem is separated from the odd-entry commutant problem. Finite coefficient algorithms solve the literal finite-dimensional computational tasks; this chapter examines what additional structural information they provide.")
talk(469,"1979-10-15","G. B. Shabat","P000861-P000864","Double translation hypersurfaces and the Lie--Wirtinger theorem",
 r"The contribution starts at the bottom of P000862 and ends midway down P000863. The catalogue names G. B. Shabat; the manuscript initial looks like \ru{Ю.}, a retained attribution discrepancy. The discussion explains the theta-divisor example and reports the classical converse, followed by Gelfand's broad integrability speculation. Genericity and the distinction between smooth Jacobians, generalized Jacobians and degenerations are indispensable.")
talk(470,"1979-10-15","Raphael Høegh-Krohn","P000862-P000866","Energy representations of current groups and Brownian paths",
 r"The actual talk occupies the lower part of P000863 and P000864--P000865, translated by Gelfand. It constructs the energy representation, states irreducibility in dimension at least three, asks about dimension two and explains the one-dimensional Brownian realization. The name bears a question mark in the notebook but is identified by the catalogue. The construction needs a Gaussian realization outside the Hilbert space and a consistent Maurer--Cartan convention. A later claimed proof in every dimension cannot settle the two-dimensional question: the primary literature explicitly identifies a gap.")

# Berezin: elementary objects and distinct questions.
add(468,"P000859","definition","Parity in a graded vector space",
 r"\(L=L_0\oplus L_1\); the notes call elements in either summand homogeneous and use parity \(\alpha(x)\in\mathbb Z_2\).",
 r"For \(\mathbb K=\mathbb R\) or \(\mathbb C\), a super vector space is a direct sum \(L_{\bar0}\oplus L_{\bar1}\). A nonzero homogeneous vector in \(L_{\bar i}\) has parity \(i\); signs in tensor products are determined modulo two.",
 r"The zero vector belongs to both summands and has no uniquely determined parity. This harmless convention is made explicit.",
 r"This is the preexisting language of superlinear algebra; compare \citet[Part I, pp.~90--130]{berezin1987superanalysis}. Publisher contents, rather than the full chapter, were checked.",["berezin1987superanalysis"],verification="publisher metadata checked")
add(468,"P000859-P000860","definition","The exterior algebra and its monomial basis",
 r"\(\Lambda\) has generators \(1,\xi_1,\ldots,\xi_N\), relations \(\xi_i\xi_j+\xi_j\xi_i=0\), ordered monomial basis, dimension \(2^N\), and \(fg=(-1)^{\alpha(f)\alpha(g)}gf\).",
 r"Over a field of characteristic different from two, \(\Lambda=\bigwedge_{\mathbb K}\mathbb K^N\), with basis \(\xi_I=\xi_{i_1}\cdots\xi_{i_k}\) for ordered subsets \(I\), including \(\xi_\varnothing=1\). Its even and odd summands have dimensions \(2^{N-1}\) when \(N\ge1\); homogeneous elements supercommute.",
 r"The restriction on characteristic is supplied; it holds for the two fields named in the notes.",
 r"Classical exterior algebra, already used throughout the earlier Berezin lectures and the 1978 BGG construction \citep[Sec.~2]{bernsteingelfandgelfand1978bundles}.",["bernsteingelfandgelfand1978bundles"],literal="correct")
add(468,"P000860","construction","The even Grassmann envelope",
 r"The initial \(L\otimes\Lambda\) definition is cancelled. The replacement is \(L(\Lambda)=\{\sum a_ie_i:\alpha(a_i)=\alpha(e_i)\}=(\Lambda\otimes L)_{\bar0}\), a left \(\Lambda_0\)-module.",
 r"For finite graded \(L\), \(L(\Lambda)=(\Lambda_{\bar0}\otimes L_{\bar0})\oplus(\Lambda_{\bar1}\otimes L_{\bar1})\). This is the even part of the graded tensor product, and is closed under multiplication by \(\Lambda_{\bar0}\).",
 r"The cancellation is substantive: the envelope is not the entire tensor product. Tensor multiplication for an algebra \(L\) requires the Koszul sign, or the equivalent coefficient-and-basis convention adopted in the lecture.",
 r"The standard functor-of-Grassmann-points construction predates this talk; see \citet[Part I, linear algebra]{berezin1987superanalysis}, and the preceding seminar occurrences 1976-406.5--9.",["berezin1987superanalysis"],verification="publisher metadata checked",literal="correct")
add(468,"P000860","conjecture","Graph analogues of the even Grassmann algebra",
 r"Gelfand proposes an analogue for every Dynkin diagram, with the ordinary example attached to \(A_n\); connected generators have product zero, disconnected ones a new product. He cites Functional Analysis 1979, no.~3.",
 r"The recorded prescription is not a complete presentation: it omits whether generators commute, square to zero, obey further path relations, and what universal property the analogue must satisfy. It therefore does not determine a unique theorem or conjecture.",
 r"The exact cited paper can be identified as Gelfand--Ponomarev's model algebras, but identifying a citation does not identify the additional proposed Grassmann analogue.",
 r"\citet[pp.~157--166]{gelfandponomarev1979model} is the exact volume/issue match, received 23 March 1979. Its graph-algebra setting supports the reference; no exact theorem equating the notebook prescription to its model algebras was verified.",["gelfandponomarev1979model"],cls="F",status=r"As of November 2026, the all-Dynkin assertion remains underdetermined by these notes. It is not entered as an open problem.",literal="not determinable",match="thematic only",verification="indirect",confidence="medium",speaker="I. M. Gelfand")
add(468,"P000860-P000861","construction","Even block supermatrices",
 r"\(L_{p,q}(\Lambda)\) has even entries in \(A_{11},A_{22}\), odd entries in \(A_{12},A_{21}\), and is an algebra.",
 r"Fix a homogeneous basis of \(\mathbb K^{p|q}\). The even endomorphisms over \(\Lambda\) are the matrices \(A=\left(\begin{smallmatrix}P&Q\\R&S\end{smallmatrix}\right)\) with \(P,S\) even and \(Q,R\) odd. With the lecture's left-module convention their composition is ordinary ordered matrix multiplication; parity is preserved.",
 r"An even supermatrix need not have all entries even. This distinction is essential: Problem 2 later asks about all-odd-entry matrices, not general odd endomorphisms of a \(p|q\) module.",
 r"This is standard superlinear algebra; \citet[Part I, pp.~90--130]{berezin1987superanalysis} is a later systematic exposition, not evidence of a new 1979 theorem.",["berezin1987superanalysis"],verification="publisher metadata checked",literal="correct")
add(468,"P000861","theorem","Cyclicity of the supertrace",
 r"\(\operatorname{str}A=\operatorname{tr}A_{11}-\operatorname{tr}A_{22}\) and \(\operatorname{str}(AB)=\operatorname{str}(BA)\).",
 r"For even supermatrices \(A,B\) over a supercommutative algebra, \(\operatorname{str}(AB)=\operatorname{str}(BA)\). For homogeneous superendomorphisms of arbitrary parity the correct general relation is \(\operatorname{str}(AB)=(-1)^{|A||B|}\operatorname{str}(BA)\).",
 r"The even-envelope domain is retained; deleting it would make the unsigned cyclicity assertion false. Off-diagonal odd products change sign on interchange, cancelling the minus in the lower-block trace.",
 r"Already part of the seminar's 1976-406.9 exposition and of Berezin's superlinear algebra \citep[Part I]{berezin1987superanalysis}.",["berezin1987superanalysis"],verification="publisher metadata checked",literal="correct")
add(468,"P000861","definition","The Berezinian and its multiplicativity",
 r"\(\operatorname{sdet}A=\det(P-QS^{-1}R)/\det S\) and \(\operatorname{sdet}(AB)=\operatorname{sdet}A\,\operatorname{sdet}B\).",
 r"For an invertible even matrix over a finite Grassmann algebra, the bodies of \(P,S\) are invertible, hence so are \(P,S\). Define \(\operatorname{Ber}A=\det(P-QS^{-1}R)(\det S)^{-1}\in\Lambda_{\bar0}^{\times}\). It is multiplicative.",
 r"Invertibility, omitted at the definition, is necessary. This rational invariant differs from the ordinary determinant even when the matrix is block diagonal: it is \(\det P/\det S\).",
 r"The Berezinian already occurs in \citet[formula~(3)]{berezinleites1975supermanifolds}; it recurs here after 1976-406.8--10. The primary metadata was rechecked and the displayed formula was checked algebraically against the notebook.",["berezinleites1975supermanifolds"],verification="indirect")
add(468,"P000861","claim","The 1|1 multiplicativity check",
 r"For \(A=\left(\begin{smallmatrix}1&\xi_1\\\xi_2&1\end{smallmatrix}\right)\), the notes calculate \(\operatorname{Ber}A=1-\xi_1\xi_2\), \(A^2\), and \(\operatorname{Ber}(A^2)=1-2\xi_1\xi_2=(\operatorname{Ber}A)^2\).",
 r"For odd generators \(\xi_1,\xi_2\) in characteristic zero, put \(t=\xi_1\xi_2\), so \(t^2=0\). Then \(A^2=\left(\begin{smallmatrix}1+t&2\xi_1\\2\xi_2&1-t\end{smallmatrix}\right)\), and the Schur-complement formula gives \((1-3t)(1+t)=1-2t\).",
 r"This verifies the particular example. It does not by itself prove multiplicativity for every \(1|1\) matrix.",
 r"A direct elementary instance of the preexisting Berezinian identity \citep[formula~(3)]{berezinleites1975supermanifolds}; the arithmetic is independently checked here.",["berezinleites1975supermanifolds"],literal="correct",verification="indirect")
add(468,"P000861","construction","The body map and invertibility",
 r"The map \(m\) is evaluation at \(\xi=0\); the body of an even supermatrix is block diagonal.",
 r"The augmentation \(m:\Lambda\to\mathbb K\) has nilpotent kernel \(J=(\xi_1,\ldots,\xi_N)\). An even supermatrix is invertible if and only if its body is invertible. Indeed, after factoring the body matrix, the remaining inverse is the finite Neumann series for \(1+K\), with \(K\in M_{p+q}(J)\).",
 r"The invertibility consequence is reconstructed to clarify the allowed change-of-basis group in the following theorem and problems.",
 r"The body construction is standard in Berezin's superanalysis \citep[Part I, linear algebra]{berezin1987superanalysis}; the finite-series argument is given explicitly here.",["berezin1987superanalysis"],verification="publisher metadata checked",literal="correct")
add(468,"P000861-P000862","theorem","Diagonalization when body eigenvalues are distinct",
 r"Over \(\mathbb C\), if \(m(A)\) has distinct eigenvalues, then an invertible \(B\) makes \(BAB^{-1}\) diagonal.",
 r"For a finite Grassmann algebra over \(\mathbb C\), let \(A\) be even and suppose all \(p+q\) eigenvalues of \(m(A)\), across both parity blocks, are distinct. There is an invertible even \(B\) with \(BAB^{-1}=\operatorname{diag}(c_1,\ldots,c_{p+q})\), where \(c_i\in\Lambda_{\bar0}\) has the corresponding eigenvalue as body.",
 r"Diagonalize the two body blocks first. At each positive Grassmann degree, remove the off-diagonal \((i,j)\) coefficient by division by the nonzero scalar \(\lambda_i-\lambda_j\); the nilpotent filtration terminates. This supplies a finite proof and specifies the parity of the conjugator.",
 r"The statement belongs to standard supermatrix perturbation theory. The later Berezin book identifies the subject, but its full theorem was not retrieved; the proof here verifies the result independently \citep[Part I]{berezin1987superanalysis}.",["berezin1987superanalysis"],verification="publisher metadata checked",literal="correct")
normalid=add(468,"P000862","problem","Canonical forms beyond simple body spectrum",
 r"\ru{Аналоги жорд. клеток здесь неизвестны. Задача 1. Сделать это (аналог норм. форм)!}",
 r"For fixed finite \(N,p,q\), classify even matrices \(A\in L_{p,q}(\Lambda_N)\) up to conjugation by invertible even matrices, without requiring distinct eigenvalues of the body. An effective canonical representative is one precise interpretation of an analogue of Jordan normal form.",
 r"The notebook does not require a short list of blocks. The chapter separates existence of a canonical algorithm from manageable block descriptions, and does not confuse wildness with nonexistence of canonical forms.",
 r"\citet[Theorems~1.1 and~1.3]{sergeichuk2000canonical} gives canonical algorithms for linear matrix problems: a verified Bielefeld preprint appeared in 1999, the journal paper in 2000, and the repository deposit in 2007. The chapter supplies the application through the faithful regular representation of the finite-dimensional even matrix algebra; the application itself is a reconstruction, not an explicit supermatrix theorem claimed in that paper.",["sergeichuk2000canonical"],cls="B",status=r"As of November 2026, the finite-\(N\) effective canonical-form interpretation is resolved by that reduction. The chapter also gives a small-\(N\) normal form and an embedding of simultaneous similarity, explaining why a Jordan-block-style classification is a stronger request.",literal="not determinable",match="partial",development="annotated",problem="GP-1979-01")
commid=add(468,"P000862","problem","Even commutants of all-odd-entry matrices",
 r"Given \(A=(a_{ik})\) with every \(a_{ik}\in\Lambda_1\), describe all \(B=(b_{ik})\) with every \(b_{ik}\in\Lambda_0\) and \(AB=BA\). Four generators are related to Yang--Mills; independent entries are said to be tractable.",
 r"For fixed \(n,N\), a specified \(A\in M_n(\Lambda_N^{\bar1})\), and a field of characteristic zero, determine the even subalgebra \(C_{\bar0}(A)=\{B\in M_n(\Lambda_N^{\bar0}):AB=BA\}\), including dimensions, bases and multiplication if desired.",
 r"Expand in the ordered monomial basis. This is the kernel of a finite \(\mathbb K\)-linear map \(B\mapsto AB-BA\), so the literal computation always has a terminating linear-algebra algorithm. A uniform structural description as \(A\) varies is a stronger question.",
 r"Searches under odd Grassmann matrices, centralizers, normal forms and Yang--Mills did not verify a publication giving the same all-\(A\) structural parametrization. The matrix-identity literature is only adjacent. The chapter solves the full \(2\times2\), four-generator case, including cubic entries; this is a bounded development proved here, not a claim of priority or that the literal finite kernel problem was open.",[],cls="C",status=r"As of November 2026, the effective finite problem is elementary and resolved. Structural classification for arbitrary \(n,N\) was not established by this search; that is a literature-identification limit, not evidence of global openness. The chapter completely develops \(n=2,N=4\).",literal="correct",match="none found",verification="unresolved lead",development="developed in this chapter",problem="GP-1979-02",worth=r"Structural rank strata are worth developing because a raw coefficient kernel conceals which nilpotent coefficients control the commutant and its jumps.",confidence="medium")
bggid=add(468,"P000862","theorem","Stable exterior modules and projective vector bundles",
 r"Gindikin associates to a graded \(\Lambda(4)\)-module the differential \(a_1\xi_1+\cdots+a_4\xi_4\), whose cohomology is concentrated at zero, and says such modules modulo trivial ones classify instantons.",
 r"For \(E=\mathbb C^4\), a finite graded \(\bigwedge E\)-module \(V\) gives a linear complex of bundles on \(\mathbb P(E)\) with differential \(\sum a_i\xi_i\). Modules whose fibre complexes have homology only in degree zero correspond to algebraic vector bundles, up to the stable equivalence generated by free exterior modules.",
 r"The anticommutation relations imply \(d^2=0\). A general module need not have the required fibre homology. Calling every resulting bundle an instanton drops the real structure and triviality on appropriate twistor lines required for the gauge-theoretic correspondence.",
 r"\citet[Secs.~3--5, Theorems~1--3]{bernsteingelfandgelfand1978bundles} already states the bundle correspondence, received 10 January 1978 and published in the 1978 volume. The recurrence is exact for bundles; the unqualified instanton identification is not. Compare 1977-437.6--12 and 1977-438.2--5.",["bernsteingelfandgelfand1978bundles"],problem="GP-1977-11",literal="correct with missing hypotheses",speaker="S. G. Gindikin")
mapsid=add(468,"P000862","problem","Construct the maps, not only the cohomology spaces",
 r"\ru{дать явную конструкцию. Не сделано (строятся пр-ва, но не отображения)}.",
 r"Given a coherent sheaf on \(\mathbb P^3\) by finite algebraic data, construct the differentials in a finite monad representing it, or the corresponding exterior-algebra resolution, rather than only the dimensions of its terms.",
 r"This makes precise the surrounding BGG/Beilinson context; the notes do not specify an input encoding or require canonical choices of bases.",
 r"\citet[Theorems~4.1 and~6.1; Sec.~5]{eisenbudfloystadschreyer2003exterior} constructs the Tate resolution and the maps of the Beilinson monad. The joint preprint appeared 20 April 2001, checked version 8 June 2001; journal publication was 2003. This answers the explicit-morphism request, although it is not the earliest possible algorithmic implementation.",["eisenbudfloystadschreyer2003exterior"],cls="B",problem="GP-1979-03",speaker="S. G. Gindikin",literal="not determinable")
grassid=add(468,"P000862","problem","A linear-algebra description for Grassmannians",
 r"\ru{сделать классиф. для грассманова мн-зия} follows the projective-space construction.",
 r"For a complex Grassmannian \(\operatorname{Gr}(k,n)\), seek a finite algebraic model for its bounded derived category of coherent sheaves, with complexes of explicit homogeneous bundles and morphisms, analogous to Beilinson's projective-space model.",
 r"The derived-category formulation is the precise reconstruction of the requested analogue. It is not an assertion that all vector bundles admit a finite numerical list.",
 r"\citet[Theorem~3.4 and Secs.~3.1--3.5]{kapranov1988homogeneous} supplies an equivalence using Schur functors of the tautological bundle. The Grassmannian result appeared first in Russian in 1984 (English translation 1985); the checked 1988 paper gives the fuller framework. Different differentials may represent the same homotopy class.",["kapranov1984grassmann","kapranov1988homogeneous"],cls="B",problem="GP-1979-04",speaker="S. G. Gindikin",literal="not determinable",match="partial")
prob("GP-1979-01","Canonical forms of even Grassmann matrices",r"Classify \(L_{p,q}(\Lambda_N)\) under its group of even units, for fixed finite \(N,p,q\), without the simple-body-spectrum hypothesis.",[normalid],r"As of November 2026, canonical algorithms follow from finite-dimensional algebra similarity and Sergeichuk's linear-matrix-problem theorem. A short Jordan-block classification is a stronger demand; the chapter supplies special cases and a simultaneous-similarity embedding.",["sergeichuk2000canonical"])
prob("GP-1979-02","Even commutants of odd Grassmann matrices",r"Given arbitrary \(A\in M_n(\Lambda_N^{\bar1})\), describe \(C_{\bar0}(A)\). The notebook specifically highlights \(N=4\).",[commid],r"As of November 2026, coefficient expansion computes the finite kernel for every \(n,N\). The chapter gives a complete structural \(n=2,N=4\) result. No claim of global openness is made for the stronger arbitrary-size classification; its exact literature status was not established.",[])
prob("GP-1977-11","Describe projective bundles by finite exterior modules",r"Describe algebraic vector bundles on complex projective space by proper finite graded exterior-algebra modules, up to addition of free modules.",["1977-438.2","1977-438.3","1977-438.4","1977-438.5",bggid],r"Established by BGG in 1978; the 1979 occurrence is exposition. Instanton bundles require extra reality and twistor-line conditions.",["bernsteingelfandgelfand1978bundles"])
